program:
import fs from 'node:fs';
import path from 'node:path';
import readline from 'node:readline';
import {createGunzip} from 'node:zlib';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
import {inspectCompletion} from './research/vendor/alpha/examples/successor-capability/out-execute/engine.mjs';
import {installedSource} from './research/vendor/alpha/examples/successor-capability/out-execute/source-manifest.mjs';
import {validateModel} from './research/vendor/alpha/examples/successor-capability/out-execute/model.mjs';
import {compileAllocation,hash} from './research/src/engine_adapter.mjs';
const began=performance.now(), cpuStart=process.cpuUsage();
const folder='research/results/holdout-01';
const bytesHash=x=>createHash('sha256').update(x).digest('hex');
const freezePath='research/protocol/source-freeze.json';
const frozen=JSON.parse(fs.readFileSync(freezePath));
const metrics=JSON.parse(fs.readFileSync(path.join(folder,'metrics.json')));
const freshInventory={};
for(const file of Object.keys(frozen.sourceInventory))freshInventory[file]=bytesHash(fs.readFileSync(path.join('research',file)));
assert.deepEqual(freshInventory,frozen.sourceInventory,'frozen installed source mismatch');
assert.equal(hash(freshInventory),frozen.sourceInventoryHash,'source inventory digest mismatch');
assert.equal(metrics.sourceInventoryHash,frozen.sourceInventoryHash,'campaign source mismatch');
const installed=await installedSource();
const proofNames=fs.readdirSync(path.join(folder,'proofs')).filter(f=>f.endsWith('.json')).sort();
assert.equal(proofNames.length,48,'expected predeclared retained count');
const wanted=new Map();
for(const name of proofNames){
 const match=/^(.*)-s(\d+)-e(\d+)-(disclosed|verified|clone)\.json$/.exec(name);
 assert(match,'unexpected proof filename');
 assert.equal(Number(match[2]),101); assert([0,6].includes(Number(match[3])));
 const key=[match[1],Number(match[2]),Number(match[3]),match[4]].join('|');
 assert(!wanted.has(key)); wanted.set(key,{name,row:null});
}
let rowsRead=0;
for await(const line of readline.createInterface({input:fs.createReadStream(path.join(folder,'missions.jsonl.gz')).pipe(createGunzip()),crlfDelay:Infinity})){
 if(!line.trim())continue; rowsRead++;
 const row=JSON.parse(line), key=[row.scenario,row.seed,row.epoch,row.method].join('|');
 if(wanted.has(key)){const selected=wanted.get(key);assert.equal(selected.row,null,'duplicate retained mission row');selected.row=row;selected.rowSha256=bytesHash(line);}
}
assert.equal(rowsRead,21504);
const checks=[],failures=[];
for(const [key,selected] of wanted){
 const before=performance.now(),cpu=process.cpuUsage();
 try{
  const {row,name,rowSha256}=selected;assert(row,'retained completion missing its mission row');
  const raw=fs.readFileSync(path.join(folder,'proofs',name));const completion=JSON.parse(raw);
  assert.equal(row.status,'complete');assert.equal(row.result.status,'COMPLETE');
  assert.equal(hash(completion),row.result.completionHash,'completion hash does not bind row');
  const compiled=compileAllocation(row.world.mission);
  assert.equal(hash(compiled),row.result.modelDigest,'unvalidated compiled model digest mismatch');
  assert.deepEqual(validateModel(compiled),completion.model,'supplied mission model differs from retained completion');
  assert.deepEqual(installed.source,completion.source,'installed inspector/compiler source differs');
  assert.deepEqual(row.result.compilerSource,completion.source,'row provenance differs');
  assert.equal(completion.parentDigest,null,'unexpected predecessor dependency');
  const checked=await inspectCompletion(completion);
  assert.equal(checked.completion.selection.status,'OPTIMAL');
  assert.equal(checked.completion.digest,completion.digest);
  assert(Number.isSafeInteger(checked.acceptance.factorLookups));
  const a=completion.artifact,plan={calibrations:[a.c0,a.c1,a.c2],slots:[a.j0,a.j1,a.j2,a.j3]};
  assert.deepEqual(plan,row.result.plan,'row plan differs from accepted witness');
  assert.equal(completion.selection.cost,row.result.objective,'row objective differs');
  checks.push({key,path:path.join(folder,'proofs',name),fileSha256:bytesHash(raw),rowSha256,completionHash:row.result.completionHash,completionDigest:completion.digest,modelDigest:row.result.modelDigest,modelRecompiled:true,installedSourceMatched:true,missionId:row.world.mission.id,status:'accepted',scope:completion.evidence.scope,authority:completion.evidence.authority,paymentRoute:completion.evidence.paymentRoute,physicalTruthEstablished:false,localAssignments:checked.localAssignments,localFactorLookups:checked.localFactorLookups,acceptance:checked.acceptance,wallMs:performance.now()-before,cpuMicros:process.cpuUsage(cpu)});
 }catch(error){failures.push({key,error:error.stack||String(error)});}
}
const report={schema:'nova-seeds-retained-native-completion-audit/v1',createdUTC:new Date().toISOString(),scope:'Read-only replay of 48 predeclared retained full native completions. This is not a second scientific experiment and does not imply every full completion was retained.',selection:{seed:101,epochs:[0,6],scenarios:metrics.scenarios,methods:['disclosed','verified','clone']},rowsRead,retainedCompletions:proofNames.length,accepted:checks.length,rejected:failures.length,sourceInventoryHash:frozen.sourceInventoryHash,sourceFreezeSha256:bytesHash(fs.readFileSync(freezePath)),missionsGzipSha256:bytesHash(fs.readFileSync(path.join(folder,'missions.jsonl.gz'))),installedSource:installed.source,sourceAuthenticity:installed.authenticity,inspectorEntrySha256:bytesHash(fs.readFileSync('research/vendor/alpha/examples/successor-capability/out-execute/engine.mjs')),campaignMetricsSha256:bytesHash(fs.readFileSync(path.join(folder,'metrics.json'))),checks,failures,wallMs:performance.now()-began,cpuMicros:process.cpuUsage(cpuStart),maxRssKiB:process.resourceUsage().maxRSS,limitations:['Checks finite supplied-model validity and row/source bindings; physical simulation truth is evaluated separately.','Local installed bytes establish exact code identity, not external attestation.','Completion authority is empty and payment route is none; mission authority is a scoped local fixture.','All campaign native solves include their native checker; verified and clone additionally invoked inspectCompletion as recorded. Only these 48 full completions are retained for post-run replay.']};
fs.writeFileSync('research/evidence/retained-completion-audit.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({retainedCompletions:report.retainedCompletions,accepted:report.accepted,rejected:report.rejected,sourceInventoryHash:report.sourceInventoryHash,wallMs:report.wallMs,cpuMicros:report.cpuMicros,maxRssKiB:report.maxRssKiB}));
if(failures.length)process.exitCode=1;
